package app.noir.mobile;
import java.io.*;
import java.nio.*;
import java.nio.charset.*;
import java.text.Normalizer;
import java.util.*;

public final class TasteCode {
    public static final String PREFIX="noir://taste/";
    public static final class Rating {public final int id,rating10;public Rating(int i,int r){id=i;rating10=r;}}
    public static final class Card {public final String name;public final int[] favorites;public final Rating[] ratings;public Card(String n,int[] f,Rating[] r){name=n;favorites=f;ratings=r;}}
    public static final class Match {public Integer score;public int overlap;public boolean correlation;public int[] bothLoved,unseenLoved,disagreements;}
    public static int id(String value){if(value==null||!value.matches("tt[0-9]+"))return 0;try{int n=Integer.parseInt(value.substring(2));return n>0?n:0;}catch(NumberFormatException e){return 0;}}
    public static String imdb(int id){return String.format(Locale.ROOT,"tt%07d",id);}
    public static String name(String value){String s=Normalizer.normalize(value==null?"":value,Normalizer.Form.NFC).trim();StringBuilder b=new StringBuilder();int length=0;for(int at=0;at<s.length();){int c=s.codePointAt(at);at+=Character.charCount(c);if(c>=0xD800&&c<=0xDFFF)c=0xFFFD;if(c<32||c==127)continue;int n=c<=127?1:c<=2047?2:c<=65535?3:4;if(length+n>64)break;b.appendCodePoint(c);length+=n;}return Normalizer.normalize(b.toString(),Normalizer.Form.NFC).trim();}
    public static Card create(String name,int[] favorites,Collection<Rating> ratings,Set<Integer> hidden){LinkedHashSet<Integer> f=new LinkedHashSet<>();for(int id:favorites)if(id>0&&(hidden==null||!hidden.contains(id))&&f.size()<4)f.add(id);TreeMap<Integer,Integer> r=new TreeMap<>();for(Rating v:ratings)if(v.id>0&&v.rating10>=1&&v.rating10<=10&&(hidden==null||!hidden.contains(v.id)))r.put(v.id,v.rating10);List<Rating> rows=new ArrayList<>();for(Map.Entry<Integer,Integer> e:r.entrySet()){if(rows.size()==60)break;rows.add(new Rating(e.getKey(),e.getValue()));}return new Card(name(name),f.stream().mapToInt(Integer::intValue).toArray(),rows.toArray(new Rating[0]));}
    // v1: u8 version, u8 UTF-8 name length + NFC bytes (<=64), u8 favorites + u32be IDs,
    // u8 rating count + sorted (u32be ID,u8 rating10). Limits: 4 favorites, 60 ratings.
    public static String encode(Card card){Card c=create(card.name,card.favorites,Arrays.asList(card.ratings),null);try{ByteArrayOutputStream bytes=new ByteArrayOutputStream();DataOutputStream out=new DataOutputStream(bytes);byte[] name=c.name.getBytes(StandardCharsets.UTF_8);out.writeByte(1);out.writeByte(name.length);out.write(name);out.writeByte(c.favorites.length);for(int id:c.favorites)out.writeInt(id);out.writeByte(c.ratings.length);for(Rating r:c.ratings){out.writeInt(r.id);out.writeByte(r.rating10);}return Base64.getUrlEncoder().withoutPadding().encodeToString(bytes.toByteArray());}catch(IOException e){throw new IllegalStateException(e);}}
    public static String link(Card card){return PREFIX+encode(card);}
    public static Card decode(String input){if(input==null||input.length()>600)return null;String code=input.trim();if(code.regionMatches(true,0,PREFIX,0,PREFIX.length()))code=code.substring(PREFIX.length());if(code.length()<6||code.length()>512||!code.matches("[A-Za-z0-9_-]+"))return null;try{byte[] bytes=Base64.getUrlDecoder().decode(code);DataInputStream in=new DataInputStream(new ByteArrayInputStream(bytes));if(in.readUnsignedByte()!=1)return null;int len=in.readUnsignedByte();if(len>64||len>in.available())return null;byte[] ns=new byte[len];in.readFully(ns);String n=StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).onUnmappableCharacter(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(ns)).toString();if(!name(n).equals(n))return null;int nf=in.readUnsignedByte();if(nf>4)return null;int[] f=new int[nf];Set<Integer> seen=new HashSet<>();for(int i=0;i<nf;i++){f[i]=in.readInt();if(f[i]<=0||!seen.add(f[i]))return null;}int nr=in.readUnsignedByte();if(nr>60||in.available()!=nr*5)return null;Rating[] r=new Rating[nr];int last=0;for(int i=0;i<nr;i++){int id=in.readInt(),v=in.readUnsignedByte();if(id<=last||v<1||v>10)return null;r[i]=new Rating(id,v);last=id;}Card c=new Card(n,f,r);return encode(c).equals(code)?c:null;}catch(IOException|IllegalArgumentException e){return null;}}
    static Set<Integer> loved(Card c){Set<Integer> ids=new TreeSet<>();for(int id:c.favorites)ids.add(id);for(Rating r:c.ratings)if(r.rating10>=8)ids.add(r.id);return ids;}
    static Set<String> tags(Set<Integer> ids,Map<Integer,String[]> genres){Set<String> result=new HashSet<>();for(int id:ids)if(genres.containsKey(id))for(String s:genres.get(id)){String v=s.trim().toLowerCase(Locale.ROOT);if(!v.isEmpty())result.add(v);}return result;}
    static <T> double jaccard(Set<T> a,Set<T> b){Set<T> union=new HashSet<>(a);union.addAll(b);Set<T> intersection=new HashSet<>(a);intersection.retainAll(b);return (double)intersection.size()/union.size();}
    public static Match compare(Card a,Card b,Map<Integer,String[]> genres){Map<Integer,Integer> ar=new TreeMap<>(),br=new TreeMap<>();for(Rating r:a.ratings)ar.put(r.id,r.rating10);for(Rating r:b.ratings)br.put(r.id,r.rating10);List<Integer> common=new ArrayList<>();for(int id:ar.keySet())if(br.containsKey(id))common.add(id);Set<Integer> al=loved(a),bl=loved(b);double total=0,weight=0;boolean correlation=false;double distance=0;for(int id:common)distance+=Math.abs(ar.get(id)-br.get(id));
        if(common.size()>=5){double ax=0,bx=0;for(int id:common){ax+=ar.get(id);bx+=br.get(id);}ax/=common.size();bx/=common.size();double xx=0,yy=0,xy=0;for(int id:common){double x=ar.get(id)-ax,y=br.get(id)-bx;xx+=x*x;yy+=y*y;xy+=x*y;}correlation=xx>0&&yy>0;total=correlation?(1+Math.max(-1,Math.min(1,xy/Math.sqrt(xx*yy))))/2:1-distance/common.size()/9;weight=1;}
        else{if(!common.isEmpty()){double w=.4*common.size()/5;total+=(1-distance/common.size()/9)*w;weight+=w;}Set<Integer> af=new HashSet<>(),bf=new HashSet<>();for(int id:a.favorites)af.add(id);for(int id:b.favorites)bf.add(id);if(!af.isEmpty()&&!bf.isEmpty()){total+=jaccard(af,bf)*.4;weight+=.4;}if(genres!=null){Set<String> ag=tags(al,genres),bg=tags(bl,genres);if(!ag.isEmpty()&&!bg.isEmpty()){total+=jaccard(ag,bg)*.2;weight+=.2;}}}
        Match m=new Match();m.score=weight==0?null:(int)Math.floor(Math.max(0,Math.min(1,total/weight))*100+.5);m.overlap=common.size();m.correlation=correlation;m.bothLoved=al.stream().filter(bl::contains).mapToInt(Integer::intValue).toArray();m.unseenLoved=bl.stream().filter(id->!ar.containsKey(id)&&!al.contains(id)).mapToInt(Integer::intValue).toArray();m.disagreements=common.stream().filter(id->Math.abs(ar.get(id)-br.get(id))>=4).sorted(Comparator.<Integer>comparingInt(id->-Math.abs(ar.get(id)-br.get(id))).thenComparingInt(id->id)).mapToInt(Integer::intValue).toArray();return m;}
}
